# SCENARIO 1: Full-stack Engineer uploading PDF generated by GapX
print("\n[SCENARIO 1] Uploading GapX Generated Full-Stack Engineer Resume PDF...")
s1_data = {
    'name': 'Sarah Chen',
    'email': 'sarah.chen@university.edu',
    'headline': 'Full Stack Software Engineer',
    'skills': ['Python', 'FastAPI', 'React', 'TypeScript', 'Node.js', 'PostgreSQL', 'Docker', 'Git', 'Data Structures', 'Algorithms', 'System Design'],
    'languages': ['Python', 'JavaScript', 'TypeScript', 'SQL'],
    'tools': ['Docker', 'Git', 'Postman', 'VS Code', 'AWS'],
    'education': 'Bachelor of Technology in Computer Science',
    'semester': 'Final Year 2026',
    'cgpa': '9.1',
    'projects': [
        {
            'title': 'AI Career Readiness Engine',
            'stack': 'React, Next.js, FastAPI, PostgreSQL, Docker',
            'bullets': [
                'Architected scalable microservices backend handling 15k requests/sec with Redis caching.',
                'Engineered automated PDF analysis pipeline reducing resume screening latency by 45%.'
            ]
        }
    ],
    'experience': [
        {
            'title': 'Software Engineering Intern',
            'company': 'Tech Corp Labs',
            'dates': 'May 2024 - August 2024',
            'bullets': [
                'Developed RESTful microservices and optimized PostgreSQL queries, improving query performance by 40%.'
            ]
        }
    ],
    'certifications': ['AWS Certified Solutions Architect', 'Meta Certified Frontend Developer']
}
pdf1 = PDFResumeGenerator.generate_resume_pdf(s1_data)
text1 = PDFExtractor.extract_text(pdf1.getvalue())
res1 = AIService.analyze_resume({
    'filename': 'Sarah_Chen_Resume.pdf',
    'is_uploaded_pdf': True,
    'extracted_text': text1,
    'target_roles': ['Software Engineer']
})
print("ATS Score:", res1['ats_score'])
print("Quality Score:", res1['resume_score'])
print("Readiness:", res1['readiness_level'])
print("Strengths:", res1['strengths'])
assert res1['ats_score'] >= 85, f"Scenario 1 score {res1['ats_score']} is too low!"
print("[PASS] Scenario 1 PASSED")

